(function () {
  if (!window.GoblubI18n) return;
  GoblubI18n.add({
    "붉은 날": ["Red Days", "Días rojos", "Hari Merah", "赤い日", "วันสีแดง", "红日", "紅日"],
    "달력": ["Calendar", "Calendario", "Kalender", "暦", "ปฏิทิน", "日历", "日曆"],
    "귀곡이 이 달 일진을 네 명부와 대조했다.": ["Gwigok has matched this month's pillars against your ledger.", "Gwigok cotejó los pilares del mes con tu libro.", "Gwigok telah mencocokkan pilar bulan ini dengan bukumu.", "鬼哭が今月の日辰をお前の冥簿と照合した。", "กวีก๊กเทียบญาณของเดือนนี้กับบัญชีของเจ้าแล้ว", "鬼哭已将本月日辰对照你的名簿。", "鬼哭已將本月日辰對照你的名簿。"],
    "붉게 물든 날은 삼가고, 금빛 나는 날에 움직여라.": ["Refrain on days dyed red; move on days that gleam gold.", "Abstente en los días teñidos de rojo; muévete en los dorados.", "Tahan diri di hari yang memerah; bergeraklah di hari yang berkilau emas.", "赤く染まった日は慎み、金色に光る日に動け。", "วันที่ย้อมแดงจงงดเว้น วันที่เรืองทองจงเคลื่อนไหว", "染红之日当慎，泛金之日当动。", "染紅之日當慎，泛金之日當動。"],
    "네 명부가 아직 여기 없구나.": ["Your ledger is not here yet.", "Tu libro aún no está aquí.", "Bukumu belum ada di sini.", "お前の冥簿はまだここに無いな。", "บัญชีของเจ้ายังไม่อยู่ที่นี่", "你的名簿还不在这里。", "你的名簿還不在這裡。"],
    "태어난 날을 적어라 — 이 달의 길흉을 짚어 주마.": ["Write your birth date — I'll point out this month's fortunes and misfortunes.", "Escribe tu fecha: te señalaré lo fasto y nefasto del mes.", "Tulis tanggal lahirmu — akan kutunjukkan untung-sial bulan ini.", "生まれた日を記せ — 今月の吉凶を指してやろう。", "จดวันเกิดมา — ข้าจะชี้ดีร้ายของเดือนนี้ให้", "写下生辰——我为你点出本月吉凶。", "寫下生辰——我為你點出本月吉凶。"],
    "◀ 지난달": ["◀ Last month", "◀ Mes pasado", "◀ Bulan lalu", "◀ 先月", "◀ เดือนก่อน", "◀ 上月", "◀ 上月"],
    "다음달 ▶": ["Next month ▶", "Próximo mes ▶", "Bulan depan ▶", "来月 ▶", "เดือนหน้า ▶", "下月 ▶", "下月 ▶"],
    "붉은 날 — 흉한 기운이 겹쳐 기운다": ["Red day — ill energies pile up and tilt", "Día rojo: energías funestas se acumulan", "Hari merah — energi buruk menumpuk dan miring", "赤い日 — 凶気が重なって傾く", "วันแดง — พลังร้ายซ้อนทับจนเอียง", "红日——凶气相叠而倾", "紅日——凶氣相疊而傾"],
    "금빛 날 — 길한 기운이 겹쳐 차오른다": ["Gold day — lucky energies pile up and swell", "Día dorado: energías propicias se colman", "Hari emas — energi baik menumpuk dan meluap", "金の日 — 吉気が重なって満ちる", "วันทอง — พลังดีซ้อนทับจนเอ่อล้น", "金日——吉气相叠而涨", "金日——吉氣相疊而漲"],
    "여느 날": ["Ordinary day", "Día común", "Hari biasa", "常の日", "วันธรรมดา", "寻常日", "尋常日"],
    "날짜를 짚으면, 그날의 일진을 읽어 주마.": ["Point to a date, and I'll read that day's pillar for you.", "Señala una fecha y te leeré su pilar.", "Tunjuk satu tanggal, kubacakan pilar hari itu.", "日付を指せば、その日の日辰を読んでやろう。", "จิ้มวันที่มา ข้าจะอ่านญาณของวันนั้นให้", "点一个日子，我为你读那日日辰。", "點一個日子，我為你讀那日日辰。"],
    "— 달이 바뀌면 다시 오너라. · 귀곡(鬼哭)": ["— When the month turns, come again. · Gwigok (鬼哭)", "— Cuando cambie el mes, vuelve. · Gwigok (鬼哭)", "— Bila bulan berganti, datanglah lagi. · Gwigok (鬼哭)", "— 月が変われば また来い。 · 鬼哭", "— เดือนเปลี่ยนเมื่อไรค่อยมาใหม่ · กวีก๊ก (鬼哭)", "——月份一换，便再来。 · 鬼哭", "——月份一換，便再來。 · 鬼哭"],
    "{Y}년 {M}월": ["{M}/{Y}", "{M}/{Y}", "{M}/{Y}", "{Y}年{M}月", "{M}/{Y}", "{Y}年{M}月", "{Y}年{M}月"],
    "{M}월 {D}일 · {GZ}({HJ})일": ["{M}/{D} · {GZ} ({HJ}) day", "{D}/{M} · día {GZ} ({HJ})", "{D}/{M} · hari {GZ} ({HJ})", "{M}月{D}日 · {GZ}（{HJ}）の日", "{D}/{M} · วัน{GZ} ({HJ})", "{M}月{D}日 · {GZ}（{HJ}）日", "{M}月{D}日 · {GZ}（{HJ}）日"],
    "{M}월엔 붉은 날이 <b>{R}일</b>, 금빛 날이 <b>{G}일</b> 적혀 있다.": ["This month holds <b>{R} red days</b> and <b>{G} gold days</b>.", "Este mes registra <b>{R} días rojos</b> y <b>{G} dorados</b>.", "Bulan ini tercatat <b>{R} hari merah</b> dan <b>{G} hari emas</b>.", "{M}月には赤い日が<b>{R}日</b>、金の日が<b>{G}日</b>記されている。", "เดือน {M} มีวันแดง <b>{R} วัน</b> วันทอง <b>{G} วัน</b>", "{M}月记有红日<b>{R}天</b>、金日<b>{G}天</b>。", "{M}月記有紅日<b>{R}天</b>、金日<b>{G}天</b>。"],
    "⚠ 흉한 기운이 겹쳐 붉게 물든 날이다. 몸을 낮춰라.": ["⚠ Ill energies overlap — a day dyed red. Keep your head down.", "⚠ Energías funestas superpuestas: día teñido de rojo. Agacha la cabeza.", "⚠ Energi buruk bertumpuk — hari yang memerah. Rendahkan dirimu.", "⚠ 凶気が重なり赤く染まった日だ。身を低くせよ。", "⚠ พลังร้ายซ้อนทับจนวันย้อมแดง จงถ่อมตัวไว้", "⚠ 凶气相叠染红之日。放低身段。", "⚠ 凶氣相疊染紅之日。放低身段。"],
    "✦ 길한 기운이 겹쳐 금빛으로 차오른 날이다. 움직여라.": ["✦ Lucky energies overlap — a day swelling gold. Move.", "✦ Energías propicias superpuestas: día colmado de oro. Muévete.", "✦ Energi baik bertumpuk — hari yang meluap keemasan. Bergeraklah.", "✦ 吉気が重なり金色に満ちた日だ。動け。", "✦ พลังดีซ้อนทับจนวันเอ่อทอง จงเคลื่อนไหว", "✦ 吉气相叠泛金之日。行动吧。", "✦ 吉氣相疊泛金之日。行動吧。"],
    "자(子)-오(午) 충. 물과 불이 정면으로 부딪히니, 머리는 차가운데 가슴이 끓는다. 감정이 시키는 결정만은 이 날 하지 마라.": ["Ja(子)-O(午) clash. Water and fire collide head-on: the head is cold while the chest boils. Whatever you do, make no emotion-driven decision this day.", "Choque Ja(子)-O(午). Agua y fuego chocan de frente: cabeza fría, pecho hirviendo. No tomes ese día decisiones dictadas por la emoción.", "Benturan Ja(子)-O(午). Air dan api bertabrakan frontal: kepala dingin tapi dada mendidih. Apa pun itu, jangan ambil keputusan yang didikte emosi di hari ini.", "子-午の沖。水と火が正面から衝突し、頭は冷たいのに胸が煮える。感情の命じる決定だけはこの日するな。", "ชง จา(子)-โอ(午) น้ำกับไฟชนกันซึ่งหน้า หัวเย็นแต่อกเดือด วันนี้ห้ามตัดสินใจตามอารมณ์เด็ดขาด", "子午相冲。水火正面相撞，头脑冷而胸中沸。唯独感情驱使的决定，这天万万别做。", "子午相沖。水火正面相撞，頭腦冷而胸中沸。唯獨感情驅使的決定，這天萬萬別做。"],
    "자오충의 날 — 마음이 널을 뛴다. 아침의 결심을 저녁에 뒤집기 쉬우니, 큰 약속은 하루 재워서 해라.": ["A Ja-O clash day — the heart seesaws. Morning resolutions flip by evening; let big promises rest a day first.", "Día de choque Ja-O: el ánimo se columpia. Lo decidido en la mañana se voltea al anochecer; deja reposar un día las grandes promesas.", "Hari benturan Ja-O — hati berayun-ayun. Tekad pagi mudah terbalik di malam hari; endapkan janji besar semalam dulu.", "子午沖の日 — 心が跳ね回る。朝の決心を夕方に覆しやすいゆえ、大きな約束は一日寝かせてからにせよ。", "วันชงจา-โอ — ใจแกว่งไปมา ปณิธานยามเช้าพลิกกลับได้ในยามเย็น สัญญาใหญ่จงหมักไว้หนึ่งวันก่อน", "子午冲之日——心绪起伏如秋千。清晨的决心入夜易翻，大的约定先搁一天再定。", "子午沖之日——心緒起伏如鞦韆。清晨的決心入夜易翻，大的約定先擱一天再定。"],
    "축(丑)-미(未) 충. 묵은 땅이 갈리는 충이라, 덮어둔 일·오래된 문서·집안일이 들춰진다. 들춰지거든 피하지 말고 이참에 정리해라.": ["Chuk(丑)-Mi(未) clash. Old ground is being tilled: covered matters, old documents, family affairs get dug up. When they surface, don't dodge — use the chance to settle them.", "Choque Chuk(丑)-Mi(未). Se remueve tierra vieja: asuntos tapados, papeles antiguos, cosas de familia salen a la luz. Si afloran, no huyas: ordénalos de una vez.", "Benturan Chuk(丑)-Mi(未). Tanah lama sedang dibajak: urusan terpendam, dokumen tua, urusan rumah terbongkar. Bila terkuak, jangan hindari — sekalian bereskan.", "丑-未の沖。古い土が耕される沖ゆえ、伏せた事・古い書類・家の事が掘り起こされる。掘り起こされたら避けず、この機に整理せよ。", "ชง ชุก(丑)-มี(未) ผืนดินเก่าถูกไถพรวน เรื่องที่กลบไว้ เอกสารเก่า เรื่องในบ้านถูกขุดขึ้นมา เมื่อโผล่มาแล้วอย่าหลบ ถือโอกาสสะสางเสีย", "丑未相冲。旧土翻耕之冲，被盖住的事、旧文书、家事都被翻出。既被翻出就别躲，趁此了结。", "丑未相沖。舊土翻耕之沖，被蓋住的事、舊文書、家事都被翻出。既被翻出就別躲，趁此了結。"],
    "축미충의 날 — 창고 바닥이 뒤집힌다. 잊고 있던 빚·약속·서류가 튀어나오기 쉬우니, 먼저 꺼내 보는 쪽이 유리하다.": ["A Chuk-Mi clash day — the storehouse floor gets flipped. Forgotten debts, promises, papers pop out; whoever brings them up first has the upper hand.", "Día de choque Chuk-Mi: se voltea el piso del granero. Deudas, promesas y papeles olvidados saltan; conviene sacarlos tú primero.", "Hari benturan Chuk-Mi — lantai gudang terbalik. Utang, janji, dokumen yang terlupa mudah mencuat; yang mengungkit duluan yang untung.", "丑未沖の日 — 蔵の底がひっくり返る。忘れていた借金・約束・書類が飛び出しやすいゆえ、先に出して見る側が有利だ。", "วันชงชุก-มี — พื้นยุ้งฉางถูกพลิก หนี้ สัญญา เอกสารที่ลืมไปโผล่ง่าย ฝ่ายที่หยิบขึ้นมาก่อนได้เปรียบ", "丑未冲之日——仓底被翻个底朝天。遗忘的债、约、文书易蹦出，先亮出来的一方占优。", "丑未沖之日——倉底被翻個底朝天。遺忘的債、約、文書易蹦出，先亮出來的一方佔優。"],
    "인(寅)-신(申) 충. 역마끼리 부딪히는 충이라 길 위가 사납다. 이동·교통·배송 — 바퀴 달린 일은 이 날 여유를 두 배로 잡아라.": ["In(寅)-Sin(申) clash. Travel stars collide — the roads run rough. Moving, traffic, deliveries: for anything on wheels, double your margin this day.", "Choque In(寅)-Sin(申). Chocan las estrellas viajeras: los caminos se embravecen. Mudanzas, tráfico, envíos: a lo que tenga ruedas, dale doble margen.", "Benturan In(寅)-Sin(申). Bintang perjalanan saling bentur — jalanan jadi ganas. Pindahan, lalu lintas, pengiriman: urusan beroda beri kelonggaran dua kali lipat.", "寅-申の沖。駅馬同士がぶつかる沖ゆえ道の上が荒れる。移動・交通・配送 — 車輪のつく事はこの日、余裕を二倍取れ。", "ชง อิน(寅)-ชิน(申) ดาวเดินทางชนกัน ถนนหนทางดุร้าย การเดินทาง จราจร ขนส่ง — เรื่องที่มีล้อจงเผื่อเวลาสองเท่า", "寅申相冲。驿马相撞之冲，路上不太平。搬迁·交通·配送——带轮子的事这天余量翻倍。", "寅申相沖。驛馬相撞之沖，路上不太平。搬遷·交通·配送——帶輪子的事這天餘量翻倍。"],
    "인신충의 날 — 일정이 어그러지기 쉽다. 갈아타는 계획·급한 출발을 삼가고, 떠나야 하거든 평소보다 일찍 나서라.": ["An In-Sin clash day — schedules slip easily. Avoid transfer plans and hasty departures; if you must leave, set out earlier than usual.", "Día de choque In-Sin: los horarios se descuadran. Evita trasbordos y salidas apuradas; si debes partir, sal más temprano.", "Hari benturan In-Sin — jadwal gampang meleset. Hindari rencana ganti kendaraan dan keberangkatan buru-buru; kalau harus pergi, berangkatlah lebih awal.", "寅申沖の日 — 日程が狂いやすい。乗り換えの計画・急な出発を控え、発つなら普段より早く出よ。", "วันชงอิน-ชิน — กำหนดการรวนง่าย เลี่ยงแผนต่อรถและการออกเดินทางกะทันหัน ถ้าจำเป็นต้องไป จงออกเร็วกว่าปกติ", "寅申冲之日——行程易乱。少排换乘计划、急行出发；非走不可，就比平时早动身。", "寅申沖之日——行程易亂。少排換乘計劃、急行出發；非走不可，就比平時早動身。"],
    "묘(卯)-유(酉) 충. 꽃과 칼이 부딪히는 충이라 관계와 약속이 베이기 쉽다. 말 한마디가 오래 남는 날이니, 농담도 골라서 해라.": ["Myo(卯)-Yu(酉) clash. Flower meets blade — relationships and promises are easily cut. One word lingers long today; choose even your jokes.", "Choque Myo(卯)-Yu(酉). Flor contra espada: lazos y promesas se cortan fácil. Una palabra dura mucho hoy; elige hasta las bromas.", "Benturan Myo(卯)-Yu(酉). Bunga bertemu pedang — hubungan dan janji mudah tersayat. Sepatah kata membekas lama hari ini; leluconmu pun pilih-pilih dulu.", "卯-酉の沖。花と刃がぶつかる沖ゆえ関係と約束が切られやすい。一言が長く残る日ゆえ、冗談も選んで言え。", "ชง มโย(卯)-ยู(酉) ดอกไม้ปะทะคมดาบ ความสัมพันธ์และสัญญาถูกบาดง่าย คำเดียวติดตรึงนาน แม้มุกตลกก็จงเลือกก่อนพูด", "卯酉相冲。花与刀相撞之冲，关系与约定易被割伤。一句话久留之日，玩笑也要挑着开。", "卯酉相沖。花與刀相撞之沖，關係與約定易被割傷。一句話久留之日，玩笑也要挑著開。"],
    "묘유충의 날 — 어긋난 약속 하나가 연쇄로 번진다. 시간 변경·취소 연락은 미루지 말고 즉시 해라.": ["A Myo-Yu clash day — one broken promise sets off a chain. Time changes and cancellations: notify at once, never later.", "Día de choque Myo-Yu: una cita fallida desata una cadena. Cambios y cancelaciones: avisa de inmediato.", "Hari benturan Myo-Yu — satu janji meleset merembet berantai. Perubahan jam dan pembatalan: kabari segera, jangan ditunda.", "卯酉沖の日 — 狂った約束一つが連鎖して広がる。時間変更・キャンセルの連絡は先送りせず即座にせよ。", "วันชงมโย-ยู — นัดที่คลาดหนึ่งนัดลามเป็นลูกโซ่ เปลี่ยนเวลาหรือยกเลิกต้องแจ้งทันที ห้ามผัด", "卯酉冲之日——一个错约连锁蔓延。改时间、取消的联络莫拖，立刻通知。", "卯酉沖之日——一個錯約連鎖蔓延。改時間、取消的聯絡莫拖，立刻通知。"],
    "진(辰)-술(戌) 충. 두 창고가 맞부딪혀 열리는 충 — 감춰둔 것이 드러나고, 큰 다툼이 붙기 쉽다. 이 날만은 비밀을 만들지도, 캐지도 마라.": ["Jin(辰)-Sul(戌) clash. Two storehouses slam open — hidden things surface and big fights ignite easily. This one day, neither make secrets nor dig for them.", "Choque Jin(辰)-Sul(戌). Dos graneros se abren de golpe: lo oculto aflora y las grandes peleas prenden fácil. Solo este día, ni crees secretos ni los caves.", "Benturan Jin(辰)-Sul(戌). Dua gudang saling menghantam hingga terbuka — yang tersembunyi terkuak, pertengkaran besar mudah tersulut. Hari ini saja, jangan membuat rahasia atau mengoreknya.", "辰-戌の沖。二つの蔵がぶつかり開く沖 — 隠したものが露わになり、大きな争いがつきやすい。この日だけは秘密を作るな、暴くな。", "ชง จิน(辰)-ซุล(戌) ยุ้งสองหลังชนกันจนเปิด — ของที่ซ่อนไว้เผยออก และการทะเลาะใหญ่ติดไฟง่าย วันนี้วันเดียว อย่าสร้างความลับและอย่าขุดคุ้ย", "辰戌相冲。两仓相撞而开之冲——藏着的显形，大争执易起。唯独这天，秘密既莫造，也莫挖。", "辰戌相沖。兩倉相撞而開之沖——藏著的顯形，大爭執易起。唯獨這天，秘密既莫造，也莫挖。"],
    "진술충의 날 — 판이 크게 흔들린다. 큰돈·큰 결정·큰 싸움, '큰'이 붙는 일은 전부 다음으로 미뤄라.": ["A Jin-Sul clash day — the whole board shakes. Big money, big decisions, big fights: postpone everything with 'big' attached.", "Día de choque Jin-Sul: el tablero entero tiembla. Dinero grande, decisiones grandes, peleas grandes: pospón todo lo que lleve 'grande'.", "Hari benturan Jin-Sul — papan permainan berguncang hebat. Uang besar, keputusan besar, pertengkaran besar: semua yang berlabel 'besar' tunda dulu.", "辰戌沖の日 — 盤面が大きく揺れる。大金・大きな決定・大喧嘩、「大」の付く事は全部次に回せ。", "วันชงจิน-ซุล — กระดานสั่นสะเทือนใหญ่ เงินก้อนใหญ่ การตัดสินใจใหญ่ การทะเลาะใหญ่ อะไรที่มีคำว่า 'ใหญ่' เลื่อนไปก่อนทั้งหมด", "辰戌冲之日——大局动摇。大钱·大决定·大架，凡带'大'字的事一律推后。", "辰戌沖之日——大局動搖。大錢·大決定·大架，凡帶『大』字的事一律推後。"],
    "사(巳)-해(亥) 충. 먼 곳의 일이 어긋나는 역마의 충이다. 여행·출장·새 시작의 첫 단추는 이 날을 피해서 끼워라.": ["Sa(巳)-Hae(亥) clash. A travel clash where distant affairs go awry. Trips, business travel, the first button of new starts — fasten them on another day.", "Choque Sa(巳)-Hae(亥). Choque viajero: lo lejano se tuerce. Viajes, comisiones, el primer botón de un comienzo: abróchalo otro día.", "Benturan Sa(巳)-Hae(亥). Benturan perjalanan di mana urusan jauh meleset. Wisata, dinas, kancing pertama dari awal yang baru — pasang di hari lain.", "巳-亥の沖。遠方の事が狂う駅馬の沖だ。旅行・出張・新しい始まりの最初のボタンは、この日を避けて掛けよ。", "ชง ซา(巳)-แฮ(亥) ชงแห่งการเดินทาง เรื่องไกลตัวคลาดเคลื่อน ทริป งานต่างเมือง กระดุมเม็ดแรกของการเริ่มใหม่ จงเลี่ยงวันนี้", "巳亥相冲。远方之事错乱的驿马之冲。旅行·出差·新开始的第一颗扣子，避开这天再扣。", "巳亥相沖。遠方之事錯亂的驛馬之沖。旅行·出差·新開始的第一顆釦子，避開這天再扣。"],
    "사해충의 날 — 물과 불이 길 위에서 만난다. 먼 약속일수록 어그러지기 쉬우니, 확인 전화 한 통이 부적이다.": ["A Sa-Hae clash day — water and fire meet on the road. The farther the appointment, the easier it slips; one confirmation call is your talisman.", "Día de choque Sa-Hae: agua y fuego se cruzan en el camino. Cuanto más lejana la cita, más fácil falla; una llamada de confirmación es tu amuleto.", "Hari benturan Sa-Hae — air dan api bertemu di jalan. Makin jauh janjinya makin mudah meleset; satu telepon konfirmasi adalah jimatmu.", "巳亥沖の日 — 水と火が道の上で出会う。遠い約束ほど狂いやすいゆえ、確認の電話一本が御守りだ。", "วันชงซา-แฮ — น้ำกับไฟพบกันกลางทาง นัดยิ่งไกลยิ่งคลาดง่าย โทรยืนยันหนึ่งสายคือยันต์", "巳亥冲之日——水火路上相逢。越远的约越易生变，一通确认电话便是护符。", "巳亥沖之日——水火路上相逢。越遠的約越易生變，一通確認電話便是護符。"],
    "자(子)-축(丑) 합 — 흙으로 맺는 합이다. 터를 다지는 날이니 저축·정리·집안일, 기반 만드는 일에 복이 붙는다.": ["Ja(子)-Chuk(丑) union — a bond sealed in earth. A day for packing the ground: savings, tidying, housework — fortune clings to foundation-building.", "Unión Ja(子)-Chuk(丑), sellada en tierra. Día de apisonar el terreno: ahorro, orden, casa — la fortuna se pega a lo fundacional.", "Persatuan Ja(子)-Chuk(丑) — ikatan yang disegel tanah. Hari memadatkan lahan: menabung, beres-beres, urusan rumah — berkah menempel pada kerja pondasi.", "子-丑の合 — 土で結ぶ合だ。地固めの日ゆえ貯蓄・整理・家事、基盤づくりに福が付く。", "ฮะ จา(子)-ชุก(丑) — พันธะที่ผนึกด้วยดิน วันบดอัดพื้นฐาน การออม จัดระเบียบ งานบ้าน — บุญเกาะงานวางราก", "子丑相合——以土缔结之合。夯实地基之日，储蓄·整理·家务，凡筑基之事皆有福。", "子丑相合——以土締結之合。夯實地基之日，儲蓄·整理·家務，凡築基之事皆有福。"],
    "자축합의 날 — 믿음이 쌓이는 합이다. 오래 갈 약속을 이 날 맺어라. 급한 이익보다 단단한 것이 남는다.": ["A Ja-Chuk union day — trust accumulates. Seal long-lasting promises today; what's solid outlasts quick gains.", "Día de unión Ja-Chuk: la confianza se acumula. Sella hoy promesas duraderas; lo sólido supera la ganancia rápida.", "Hari persatuan Ja-Chuk — kepercayaan menumpuk. Ikat janji jangka panjang hari ini; yang kokoh lebih awet daripada untung cepat.", "子丑合の日 — 信頼が積もる合だ。長く続く約束をこの日結べ。急な利より堅いものが残る。", "วันฮะจา-ชุก — ความไว้ใจสั่งสม จงผูกสัญญาระยะยาววันนี้ ของแน่นหนาคงอยู่กว่ากำไรเร่งด่วน", "子丑合之日——信任累积之合。长久之约今日缔结。比起急利，坚实者长存。", "子丑合之日——信任累積之合。長久之約今日締結。比起急利，堅實者長存。"],
    "인(寅)-해(亥) 합 — 나무로 맺는 합이다. 새싹이 돋는 기운이니 시작·배움·씨 뿌리는 일은 이 날이 제일 좋다.": ["In(寅)-Hae(亥) union — a bond sealed in wood. Sprouting energy: starts, learning, seed-sowing are best done this day.", "Unión In(寅)-Hae(亥), sellada en madera. Energía de brotes: comenzar, aprender, sembrar — este día es el mejor.", "Persatuan In(寅)-Hae(亥) — ikatan yang disegel kayu. Energi bertunas: memulai, belajar, menabur benih paling baik di hari ini.", "寅-亥の合 — 木で結ぶ合だ。新芽の吹く気ゆえ、始まり・学び・種まきはこの日が一番良い。", "ฮะ อิน(寅)-แฮ(亥) — พันธะที่ผนึกด้วยไม้ พลังหน่ออ่อนแตกยอด การเริ่มต้น การเรียน การหว่านเมล็ด วันนี้ดีที่สุด", "寅亥相合——以木缔结之合。新芽萌发之气，开始·学习·播种之事，这天最好。", "寅亥相合——以木締結之合。新芽萌發之氣，開始·學習·播種之事，這天最好。"],
    "인해합의 날 — 자라나는 합이다. 새 공부·새 운동·새 사람, '새'가 붙는 일에 순풍이 분다.": ["An In-Hae union day — a growing union. New studies, new workouts, new people: a tailwind blows on all things 'new'.", "Día de unión In-Hae: una unión que crece. Nuevos estudios, ejercicios, personas: viento a favor en todo lo 'nuevo'.", "Hari persatuan In-Hae — persatuan yang bertumbuh. Belajar baru, olahraga baru, orang baru: angin buritan bertiup pada semua yang 'baru'.", "寅亥合の日 — 育つ合だ。新しい勉強・新しい運動・新しい人、「新」の付く事に追い風が吹く。", "วันฮะอิน-แฮ — ฮะที่เติบโต การเรียนใหม่ กีฬาใหม่ คนใหม่ อะไรที่มีคำว่า 'ใหม่' มีลมส่งทั้งนั้น", "寅亥合之日——生长之合。新学业·新运动·新朋友，凡带'新'字的事皆有顺风。", "寅亥合之日——生長之合。新學業·新運動·新朋友，凡帶『新』字的事皆有順風。"],
    "묘(卯)-술(戌) 합 — 불로 맺는 합이다. 온기가 도는 날이니 화해·고백·안부, 마음 데우는 일을 이 날 해라.": ["Myo(卯)-Sul(戌) union — a bond sealed in fire. Warmth circulates: reconciliation, confessions, check-ins — do the heart-warming things today.", "Unión Myo(卯)-Sul(戌), sellada en fuego. Circula el calor: reconciliaciones, confesiones, saludos — haz hoy lo que temple corazones.", "Persatuan Myo(卯)-Sul(戌) — ikatan yang disegel api. Kehangatan beredar: berdamai, menyatakan cinta, menyapa — kerjakan yang menghangatkan hati hari ini.", "卯-戌の合 — 火で結ぶ合だ。温もりが巡る日ゆえ、仲直り・告白・安否、心を温める事をこの日にせよ。", "ฮะ มโย(卯)-ซุล(戌) — พันธะที่ผนึกด้วยไฟ ความอบอุ่นหมุนเวียน คืนดี สารภาพรัก ทักถาม — งานอุ่นใจจงทำวันนี้", "卯戌相合——以火缔结之合。暖意流转之日，和解·告白·问候，暖心之事今日做。", "卯戌相合——以火締結之合。暖意流轉之日，和解·告白·問候，暖心之事今日做。"],
    "묘술합의 날 — 식은 것이 다시 데워진다. 멀어진 인연에게 먼저 연락해 보아라, 평소의 세 배로 먹힌다.": ["A Myo-Sul union day — what cooled warms again. Reach out first to a distant bond; it lands three times harder than usual.", "Día de unión Myo-Sul: lo frío se recalienta. Contacta primero a un lazo alejado; funciona el triple de lo normal.", "Hari persatuan Myo-Sul — yang dingin menghangat kembali. Hubungi duluan orang yang menjauh; efeknya tiga kali lipat dari biasanya.", "卯戌合の日 — 冷めたものがまた温まる。遠のいた縁に先に連絡してみよ、普段の三倍効く。", "วันฮะมโย-ซุล — ของที่เย็นชืดถูกอุ่นใหม่ ทักไปหาคนที่ห่างเหินก่อนสิ ได้ผลสามเท่าของปกติ", "卯戌合之日——凉了的重新回温。先联络疏远的缘分，效果是平日三倍。", "卯戌合之日——涼了的重新回溫。先聯絡疏遠的緣分，效果是平日三倍。"],
    "진(辰)-유(酉) 합 — 쇠로 맺는 합이다. 결실을 거두는 날이니 계약·마무리·성과 보고, 매듭짓는 일에 운이 붙는다.": ["Jin(辰)-Yu(酉) union — a bond sealed in metal. A harvest day: contracts, closings, results reports — luck clings to knot-tying work.", "Unión Jin(辰)-Yu(酉), sellada en metal. Día de cosecha: contratos, cierres, informes — la suerte se pega a lo que anuda.", "Persatuan Jin(辰)-Yu(酉) — ikatan yang disegel logam. Hari panen: kontrak, penutupan, laporan hasil — keberuntungan menempel pada kerja penyelesaian.", "辰-酉の合 — 金で結ぶ合だ。実りを収める日ゆえ契約・仕上げ・成果報告、締めくくる事に運が付く。", "ฮะ จิน(辰)-ยู(酉) — พันธะที่ผนึกด้วยโลหะ วันเก็บเกี่ยว สัญญา งานปิดท้าย รายงานผล — โชคเกาะงานผูกปม", "辰酉相合——以金缔结之合。收获之日，签约·收尾·汇报成果，凡收官之事皆有运。", "辰酉相合——以金締結之合。收穫之日，簽約·收尾·匯報成果，凡收官之事皆有運。"],
    "진유합의 날 — 여문 것을 거두는 합이다. 끌어온 결정이 있다면 이 날 도장을 찍어라.": ["A Jin-Yu union day — reaping what has ripened. If a decision has dragged on, stamp the seal today.", "Día de unión Jin-Yu: se recoge lo maduro. Si una decisión se arrastró, séllala hoy.", "Hari persatuan Jin-Yu — memetik yang sudah matang. Kalau ada keputusan yang berlarut, bubuhkan stempel hari ini.", "辰酉合の日 — 実ったものを収める合だ。引きずってきた決定があるならこの日、判を押せ。", "วันฮะจิน-ยู — เก็บเกี่ยวสิ่งที่สุกงอม ถ้ามีการตัดสินใจที่ยืดเยื้อ จงประทับตราวันนี้", "辰酉合之日——收熟果之合。若有拖延的决定，今日盖章。", "辰酉合之日——收熟果之合。若有拖延的決定，今日蓋章。"],
    "사(巳)-신(申) 합 — 물로 맺는 합이다. 꾀가 트이는 날이니 협상·흥정·조율, 머리 쓰는 일에 이 날을 써라.": ["Sa(巳)-Sin(申) union — a bond sealed in water. Wits open up: use this day for negotiation, bargaining, coordination — anything that takes brains.", "Unión Sa(巳)-Sin(申), sellada en agua. Se abre el ingenio: usa el día para negociar, regatear, coordinar — lo que pida cabeza.", "Persatuan Sa(巳)-Sin(申) — ikatan yang disegel air. Akal terbuka: pakai hari ini untuk negosiasi, tawar-menawar, koordinasi — kerja yang butuh otak.", "巳-申の合 — 水で結ぶ合だ。知恵が開ける日ゆえ交渉・駆け引き・調整、頭を使う事にこの日を使え。", "ฮะ ซา(巳)-ชิน(申) — พันธะที่ผนึกด้วยน้ำ วันที่ปัญญาเปิด เจรจา ต่อรอง ประสานงาน — งานใช้สมองจงใช้วันนี้", "巳申相合——以水缔结之合。智谋开窍之日，谈判·议价·协调，用脑之事用在这天。", "巳申相合——以水締結之合。智謀開竅之日，談判·議價·協調，用腦之事用在這天。"],
    "사신합의 날 — 지혜가 흐르는 합이다. 얽힌 문제를 이 날 풀어라, 평소 안 보이던 수가 보인다.": ["A Sa-Sin union day — wisdom flows. Untangle the knotted problem today; moves you couldn't see before come into view.", "Día de unión Sa-Sin: fluye la sabiduría. Desenreda hoy el problema atascado; verás jugadas antes invisibles.", "Hari persatuan Sa-Sin — kebijaksanaan mengalir. Urai masalah yang kusut hari ini; langkah yang biasanya tak terlihat jadi tampak.", "巳申合の日 — 知恵が流れる合だ。絡んだ問題をこの日解け、普段見えぬ手が見える。", "วันฮะซา-ชิน — ปัญญาไหลลื่น จงแก้ปัญหาที่พันกันวันนี้ จะเห็นหมากที่ปกติมองไม่เห็น", "巳申合之日——智慧流淌之合。纠结的问题今日解，平时看不见的招数会显现。", "巳申合之日——智慧流淌之合。糾結的問題今日解，平時看不見的招數會顯現。"],
    "오(午)-미(未) 합 — 해와 달이 만나는 합이다. 마음이 맞춰지는 날이니 소개·모임·첫 만남을 이 날로 잡아라.": ["O(午)-Mi(未) union — sun and moon meet. Hearts align today: set introductions, gatherings, first meetings on this day.", "Unión O(午)-Mi(未): se encuentran sol y luna. Los corazones se acompasan: agenda presentaciones, reuniones y primeros encuentros hoy.", "Persatuan O(午)-Mi(未) — matahari dan bulan bertemu. Hati saling selaras: jadwalkan perkenalan, kumpul, pertemuan pertama di hari ini.", "午-未の合 — 日と月が出会う合だ。心が合わさる日ゆえ、紹介・集まり・初対面はこの日に取れ。", "ฮะ โอ(午)-มี(未) — ตะวันกับจันทร์มาพบกัน วันที่ใจตรงกัน นัดแนะนำตัว งานรวมตัว การพบครั้งแรก จงกำหนดวันนี้", "午未相合——日月相会之合。心意相合之日，介绍·聚会·初见，都定在这天。", "午未相合——日月相會之合。心意相合之日，介紹·聚會·初見，都定在這天。"],
    "오미합의 날 — 음과 양이 나란히 선다. 사람 사이의 일은 무엇이든 이 날이 순하다.": ["An O-Mi union day — yin and yang stand side by side. Anything between people runs gentle this day.", "Día de unión O-Mi: yin y yang se alinean. Todo lo que sea entre personas fluye manso hoy.", "Hari persatuan O-Mi — yin dan yang berdiri berdampingan. Segala urusan antarmanusia berjalan jinak hari ini.", "午未合の日 — 陰と陽が並び立つ。人の間の事は何でもこの日、素直に運ぶ。", "วันฮะโอ-มี — หยินหยางยืนเคียงกัน เรื่องระหว่างคนล้วนราบรื่นในวันนี้", "午未合之日——阴阳并立。凡人与人之间的事，这天都顺。", "午未合之日——陰陽並立。凡人與人之間的事，這天都順。"],
    "이 날 지지가 네 일지와 같은 삼합의 반쪽이다 — 수국(水局)의 기운. 뜻 맞는 이와 손잡으면 지혜가 배로 흐른다.": ["This day's branch is half of your day branch's triple harmony — Water Bureau (水局) energy. Join hands with a like-minded soul and wisdom flows double.", "La rama del día es media armonía triple con la tuya: energía del Buró de Agua (水局). Da la mano a un afín y la sabiduría fluye al doble.", "Cabang hari ini adalah separuh dari samhap cabang harimu — energi Kubu Air (水局). Bergandengan dengan yang sehati, kebijaksanaan mengalir dua kali lipat.", "この日の地支はお前の日支と同じ三合の片割れだ — 水局の気。志の合う者と手を組めば知恵が倍に流れる。", "กิ่งวันนี้คือครึ่งซัมฮะเดียวกับกิ่งวันเจ้า — พลังชลวรรค (水局) จับมือกับคนใจตรงกัน ปัญญาไหลทวีคูณ", "此日地支与你日支同属三合之半——水局之气。与志同者携手，智慧倍流。", "此日地支與你日支同屬三合之半——水局之氣。與志同者攜手，智慧倍流。"],
    "이 날 지지가 네 일지와 삼합의 반쪽을 이룬다 — 화국(火局)의 기운. 드러내는 일·발표·홍보에 힘이 실린다.": ["This day's branch forms half a triple harmony with yours — Fire Bureau (火局) energy. Power flows into showing, presenting, promoting.", "La rama del día forma media armonía con la tuya: energía del Buró de Fuego (火局). Fuerza para mostrar, presentar, promocionar.", "Cabang hari ini membentuk separuh samhap dengan milikmu — energi Kubu Api (火局). Tenaga mengalir ke urusan tampil, presentasi, promosi.", "この日の地支はお前の日支と三合の片割れを成す — 火局の気。表に出す事・発表・広報に力が乗る。", "กิ่งวันนี้ก่อครึ่งซัมฮะกับของเจ้า — พลังอัคนีวรรค (火局) งานเปิดตัว พรีเซนต์ โปรโมต มีพลังหนุน", "此日地支与你日支成三合之半——火局之气。展示·发表·宣传之事有力加持。", "此日地支與你日支成三合之半——火局之氣。展示·發表·宣傳之事有力加持。"],
    "이 날 지지가 네 일지와 삼합의 반쪽이다 — 금국(金局)의 기운. 거두고 정리하는 일, 매듭짓는 일이 순하다.": ["This day's branch is half of your triple harmony — Metal Bureau (金局) energy. Harvesting, sorting, tying off loose ends run gentle.", "La rama del día es media armonía con la tuya: energía del Buró de Metal (金局). Cosechar, ordenar y rematar fluyen mansos.", "Cabang hari ini separuh samhap dengan milikmu — energi Kubu Logam (金局). Memanen, membereskan, menyimpulkan berjalan jinak.", "この日の地支はお前の日支と三合の片割れだ — 金局の気。収めて整理する事、締めくくる事が素直に運ぶ。", "กิ่งวันนี้คือครึ่งซัมฮะกับของเจ้า — พลังโลหวรรค (金局) งานเก็บเกี่ยว จัดระเบียบ ผูกปมจบ ล้วนราบรื่น", "此日地支与你日支同属三合之半——金局之气。收获整理、收官之事皆顺。", "此日地支與你日支同屬三合之半——金局之氣。收穫整理、收官之事皆順。"],
    "이 날 지지가 네 일지와 삼합의 반쪽을 이룬다 — 목국(木局)의 기운. 키우는 일·배움·새 시작에 물이 오른다.": ["This day's branch forms half a triple harmony with yours — Wood Bureau (木局) energy. Nurturing, learning, new starts come into full sap.", "La rama del día forma media armonía con la tuya: energía del Buró de Madera (木局). Criar, aprender y empezar cobran savia.", "Cabang hari ini membentuk separuh samhap dengan milikmu — energi Kubu Kayu (木局). Membesarkan, belajar, awal baru sedang bergetah subur.", "この日の地支はお前の日支と三合の片割れを成す — 木局の気。育てる事・学び・新しい始まりに水が上がる。", "กิ่งวันนี้ก่อครึ่งซัมฮะกับของเจ้า — พลังพฤกษวรรค (木局) งานฟูมฟัก การเรียน การเริ่มใหม่ กำลังชุ่มฉ่ำ", "此日地支与你日支成三合之半——木局之气。培育·学习·新开始，正当水涨。", "此日地支與你日支成三合之半——木局之氣。培育·學習·新開始，正當水漲。"],
    "이 날 지지가 네 일지와 형(刑)을 이룬다. 은혜가 원수 되기 쉬운 마찰의 기운 — 잘해 준 일일수록 생색내지 말고, 남의 일에 깊이 끼지 마라.": ["This day's branch forms a punishment (刑) with yours. Friction where favors turn to grudges — don't fish for credit on kindnesses, and don't wade deep into others' affairs.", "La rama del día forma castigo (刑) con la tuya. Fricción donde el favor se vuelve rencor: no presumas tus bondades ni te metas hondo en asuntos ajenos.", "Cabang hari ini membentuk hukuman (刑) dengan milikmu. Gesekan di mana budi mudah jadi dendam — jangan mengungkit kebaikanmu, dan jangan terlalu dalam ikut urusan orang.", "この日の地支はお前の日支と刑を成す。恩が仇になりやすい摩擦の気 — 良くしてやった事ほど恩に着せず、他人の事に深く関わるな。", "กิ่งวันนี้ก่อฮย็อง (刑) กับของเจ้า พลังเสียดทานที่บุญคุณกลายเป็นความแค้นง่าย — ยิ่งทำดีให้ใครยิ่งอย่าทวงบุญคุณ และอย่ายุ่งเรื่องคนอื่นลึกเกิน", "此日地支与你日支成刑。恩易成仇的摩擦之气——越是施过恩越莫居功，他人之事莫深涉。", "此日地支與你日支成刑。恩易成仇的摩擦之氣——越是施過恩越莫居功，他人之事莫深涉。"],
    "이 날 지지가 네 일지와 원진(怨嗔)이다. 이유 없이 서로 미운 기운이 끼니, 사소한 오해는 그 자리에서 풀어라. 하루 묵히면 열흘 간다.": ["This day's branch is in wonjin (怨嗔) with yours. A haze of causeless mutual dislike sets in — clear small misunderstandings on the spot. Aged one day, they last ten.", "La rama del día está en wonjin (怨嗔) con la tuya. Se cuela una inquina sin motivo: aclara los malentendidos pequeños al instante. Un día guardado dura diez.", "Cabang hari ini ber-wonjin (怨嗔) dengan milikmu. Kabut saling sebal tanpa sebab menyusup — salah paham kecil urai di tempat. Didiamkan sehari, awet sepuluh hari.", "この日の地支はお前の日支と怨嗔だ。理由なく憎み合う気が差すゆえ、些細な誤解はその場で解け。一日寝かせば十日続く。", "กิ่งวันนี้เป็นว็อนจิน (怨嗔) กับของเจ้า พลังเกลียดกันไร้เหตุผลแทรกเข้ามา เข้าใจผิดเล็กน้อยจงเคลียร์ตรงนั้น หมักไว้วันเดียวอยู่สิบวัน", "此日地支与你日支犯怨嗔。无端互厌之气弥漫，小误会当场解开。搁一天，缠十天。", "此日地支與你日支犯怨嗔。無端互厭之氣瀰漫，小誤會當場解開。擱一天，纏十天。"],
    "게다가 이 날 일진 천간이 네 일간과 합(合)을 이룬다 — 밖에서 오는 제안·부탁에 귀를 열어 두어라, 네게 필요한 것이 실려 온다.": ["What's more, this day's heavenly stem unites (合) with your day master — keep your ears open to offers and requests from outside; what you need rides in on them.", "Además, el tronco del día se une (合) a tu día: abre el oído a propuestas y pedidos de fuera; lo que necesitas llega montado en ellos.", "Lagi pula batang langit hari ini berpadu (合) dengan penguasa harimu — buka telinga untuk tawaran dan permintaan dari luar; yang kaubutuhkan terangkut di situ.", "しかもこの日の日辰天干がお前の日干と合を成す — 外から来る提案・頼みに耳を開けておけ、お前に必要なものが載って来る。", "ยิ่งกว่านั้น ลำต้นฟ้าวันนี้เกิดฮะกับธาตุวันเจ้า — เปิดหูรับข้อเสนอและคำขอจากภายนอก สิ่งที่เจ้าต้องการจะติดมากับมัน", "而且此日日辰天干与你日主相合——对外来的提议·请托敞开耳朵，你需要的正随之而来。", "而且此日日辰天干與你日主相合——對外來的提議·請託敞開耳朵，你需要的正隨之而來。"],
    "일진 천간이 네 일간을 정면으로 친다(沖) — 위에서 오는 압박, 갑작스런 변수에 대비하라. 중요한 결정 하나는 하루 미루는 것이 이 날의 부적이다.": ["The day's heavenly stem strikes your day master head-on (沖) — brace for pressure from above and sudden variables. Postponing one important decision by a day is this day's talisman.", "El tronco del día golpea de frente tu día (沖): prepárate para presión de arriba y variables súbitas. Posponer una decisión importante un día es el amuleto de hoy.", "Batang langit hari ini menghantam penguasa harimu frontal (沖) — bersiaplah untuk tekanan dari atas dan variabel mendadak. Menunda satu keputusan penting sehari adalah jimat hari ini.", "日辰天干がお前の日干を正面から打つ（沖） — 上からの圧、急な変数に備えよ。重要な決定一つを一日延ばすのがこの日の御守りだ。", "ลำต้นฟ้าวันนี้ชงธาตุวันเจ้าซึ่งหน้า — เตรียมรับแรงกดจากเบื้องบนและตัวแปรฉับพลัน การเลื่อนการตัดสินใจสำคัญหนึ่งเรื่องไปหนึ่งวันคือยันต์ของวันนี้", "日辰天干正面冲你日主——防上方之压、突来变数。把一个重要决定推迟一天，便是此日护符。", "日辰天干正面沖你日主——防上方之壓、突來變數。把一個重要決定推遲一天，便是此日護符。"],
    "이 날은 네 명부의 공망(空亡) — 기운이 비는 날이다. 새로 벌이는 일엔 힘이 실리지 않으니, 채우기보다 비우는 일(정리·휴식·마음 청소)에 써라.": ["This day is your ledger's gongmang (空亡) — a day of empty energy. New ventures carry no force; spend it on emptying rather than filling — tidying, resting, sweeping the heart.", "Este día es el gongmang (空亡) de tu libro: energía vacía. Lo nuevo no lleva fuerza; úsalo para vaciar, no llenar — ordenar, descansar, limpiar el corazón.", "Hari ini adalah gongmang (空亡) bukumu — hari yang energinya kosong. Usaha baru tak bertenaga; pakailah untuk mengosongkan alih-alih mengisi — beres-beres, istirahat, membersihkan hati.", "この日はお前の冥簿の空亡 — 気の空く日だ。新しく始める事には力が乗らぬゆえ、満たすより空ける事（整理・休息・心の掃除）に使え。", "วันนี้คือกงมัง (空亡) ในบัญชีเจ้า — วันที่พลังว่างเปล่า งานริเริ่มใหม่ไร้แรงหนุน จงใช้กับการปล่อยวางแทนการเติม — จัดระเบียบ พักผ่อน กวาดใจ", "此日乃你名簿之空亡——气虚之日。新起之事不着力，与其填满不如放空——整理·休息·扫心。", "此日乃你名簿之空亡——氣虛之日。新起之事不著力，與其填滿不如放空——整理·休息·掃心。"],
    "쥐(子)의 시각이 도는 날 — 민첩한 쪽이 이긴다. 미루던 잔일을 아침에 해치워라.": ["A day the Rat's (子) hour turns — the nimble one wins. Knock out postponed chores in the morning.", "Día en que gira la hora de la Rata (子): gana el ágil. Despacha por la mañana las tareas aplazadas.", "Hari saat jam Tikus (子) berputar — yang gesit menang. Habisi pekerjaan kecil yang tertunda di pagi hari.", "子の刻が巡る日 — 素早い方が勝つ。先延ばしの雑事を朝のうちに片付けよ。", "วันที่ยามชวด (子) หมุนเวียน — ฝ่ายคล่องแคล่วชนะ งานจุกจิกที่ค้าง จัดการให้จบตอนเช้า", "子鼠时气流转之日——敏捷者胜。拖着的杂事晨间解决。", "子鼠時氣流轉之日——敏捷者勝。拖著的雜事晨間解決。"],
    "소(丑)의 걸음이 도는 날 — 느려도 확실한 진행이 답이다. 서두르는 자가 먼저 넘어진다.": ["A day the Ox's (丑) gait turns — slow but sure is the answer. The hurried one stumbles first.", "Día del paso del Buey (丑): lento pero seguro. El apurado tropieza primero.", "Hari saat langkah Kerbau (丑) berputar — pelan tapi pasti itulah jawabannya. Yang terburu-buru jatuh duluan.", "丑の歩みが巡る日 — 遅くとも確実な進行が答えだ。急ぐ者が先に転ぶ。", "วันที่ย่างก้าวฉลู (丑) หมุนเวียน — ช้าแต่ชัวร์คือคำตอบ คนรีบล้มก่อน", "丑牛步气流转之日——慢而确实是答案。急者先摔。", "丑牛步氣流轉之日——慢而確實是答案。急者先摔。"],
    "호랑이(寅)의 기세가 도는 날 — 과감한 한 걸음에 힘이 붙는다. 다만 어흥은 한 번이면 족하다.": ["A day the Tiger's (寅) vigor turns — a bold step gains power. But one roar is plenty.", "Día del brío del Tigre (寅): el paso audaz cobra fuerza. Pero con un rugido basta.", "Hari saat wibawa Macan (寅) berputar — satu langkah berani mendapat tenaga. Tapi mengaum sekali saja cukup.", "寅の勢いが巡る日 — 大胆な一歩に力が付く。ただし咆哮は一度で足りる。", "วันที่พลังขาล (寅) หมุนเวียน — ก้าวที่กล้ามีแรงหนุน แต่คำรามครั้งเดียวก็พอ", "寅虎气势流转之日——果敢一步自有力。但虎啸一声足矣。", "寅虎氣勢流轉之日——果敢一步自有力。但虎嘯一聲足矣。"],
    "토끼(卯)의 감각이 도는 날 — 눈썰미가 산다. 다듬고 꾸미는 일을 이 날 해라.": ["A day the Rabbit's (卯) senses turn — your keen eye comes alive. Do the trimming and adorning today.", "Día del olfato del Conejo (卯): despierta el buen ojo. Pule y adorna hoy.", "Hari saat indera Kelinci (卯) berputar — kejelian matamu hidup. Kerjakan urusan memoles dan menghias hari ini.", "卯の感覚が巡る日 — 目利きが冴える。整えて飾る事をこの日にせよ。", "วันที่ประสาทเถาะ (卯) หมุนเวียน — สายตาเฉียบขึ้น งานตกแต่งเจียระไนจงทำวันนี้", "卯兔感官流转之日——眼力正好。修饰装点之事今日做。", "卯兔感官流轉之日——眼力正好。修飾裝點之事今日做。"],
    "용(辰)의 구름이 도는 날 — 스케일 큰 그림을 그리기 좋다. 계획은 크게, 지출은 작게.": ["A day the Dragon's (辰) clouds turn — good for painting grand pictures. Plan big, spend small.", "Día de las nubes del Dragón (辰): bueno para trazar en grande. Planes grandes, gastos pequeños.", "Hari saat awan Naga (辰) berputar — bagus untuk melukis gambar besar. Rencana besar, pengeluaran kecil.", "辰の雲が巡る日 — スケールの大きい絵を描くのに良い。計画は大きく、支出は小さく。", "วันที่เมฆมะโรง (辰) หมุนเวียน — เหมาะวาดภาพใหญ่ แผนให้ใหญ่ รายจ่ายให้เล็ก", "辰龙云气流转之日——宜绘大图。计划要大，支出要小。", "辰龍雲氣流轉之日——宜繪大圖。計劃要大，支出要小。"],
    "뱀(巳)의 직감이 도는 날 — 촉이 예리해진다. 어딘가 께름칙하면 그 느낌이 맞다.": ["A day the Snake's (巳) intuition turns — your instincts sharpen. If something feels off, that feeling is right.", "Día de la intuición de la Serpiente (巳): se afila el instinto. Si algo te da mala espina, la espina acierta.", "Hari saat intuisi Ular (巳) berputar — nalurimu menajam. Kalau ada yang terasa janggal, perasaan itu benar.", "巳の直感が巡る日 — 勘が鋭くなる。どこか引っかかるなら、その感覚が正しい。", "วันที่ญาณมะเส็ง (巳) หมุนเวียน — สัมผัสไวขึ้น ถ้ารู้สึกตะหงิด ๆ ความรู้สึกนั้นถูกแล้ว", "巳蛇直觉流转之日——第六感变利。若觉哪里不对劲，那感觉是对的。", "巳蛇直覺流轉之日——第六感變利。若覺哪裡不對勁，那感覺是對的。"],
    "말(馬·午)의 발굽이 도는 날 — 활동량을 늘려라. 몸을 움직인 만큼 운이 돈다.": ["A day the Horse's (午) hooves turn — increase your activity. Luck circulates as much as your body moves.", "Día de los cascos del Caballo (午): aumenta tu actividad. La suerte circula cuanto te muevas.", "Hari saat tapak Kuda (午) berputar — tambah aktivitasmu. Keberuntungan berputar sebanyak tubuhmu bergerak.", "午の蹄が巡る日 — 活動量を増やせ。体を動かした分だけ運が回る。", "วันที่กีบมะเมีย (午) หมุนเวียน — เพิ่มการเคลื่อนไหว ขยับกายเท่าไรโชคหมุนเท่านั้น", "午马蹄声流转之日——加大活动量。身体动多少，运就转多少。", "午馬蹄聲流轉之日——加大活動量。身體動多少，運就轉多少。"],
    "양(未)의 온기가 도는 날 — 화해와 나눔이 순하다. 밥 한 끼 사는 것이 부적이 된다.": ["A day the Goat's (未) warmth turns — reconciliation and sharing run gentle. Buying someone a meal becomes a talisman.", "Día del calor de la Cabra (未): reconciliar y compartir fluye. Invitar una comida se vuelve amuleto.", "Hari saat kehangatan Kambing (未) berputar — berdamai dan berbagi berjalan jinak. Mentraktir semangkuk makan jadi jimat.", "未の温もりが巡る日 — 仲直りと分かち合いが素直に運ぶ。飯を一食おごる事が御守りになる。", "วันที่ไออุ่นมะแม (未) หมุนเวียน — การคืนดีและแบ่งปันราบรื่น เลี้ยงข้าวสักมื้อกลายเป็นยันต์", "未羊暖意流转之日——和解与分享皆顺。请一顿饭便是护符。", "未羊暖意流轉之日——和解與分享皆順。請一頓飯便是護符。"],
    "원숭이(申)의 재주가 도는 날 — 손 쓰는 일이 술술 풀린다. 고장 난 것을 이 날 고쳐라.": ["A day the Monkey's (申) craft turns — handiwork unravels smoothly. Fix what's broken today.", "Día de la maña del Mono (申): lo manual fluye. Repara hoy lo averiado.", "Hari saat kecakapan Monyet (申) berputar — kerja tangan terurai lancar. Perbaiki yang rusak hari ini.", "申の才が巡る日 — 手を使う事がすらすら解ける。壊れた物をこの日直せ。", "วันที่ฝีมือวอก (申) หมุนเวียน — งานฝีมือคลี่คลายลื่นไหล ของที่พังจงซ่อมวันนี้", "申猴巧手流转之日——动手的活儿顺顺当当。坏了的东西今日修。", "申猴巧手流轉之日——動手的活兒順順當當。壞了的東西今日修。"],
    "닭(酉)의 부리가 도는 날 — 꼼꼼함이 무기다. 마무리와 점검, 오탈자 잡기에 좋다.": ["A day the Rooster's (酉) beak turns — meticulousness is your weapon. Good for finishing, checking, catching typos.", "Día del pico del Gallo (酉): la minucia es tu arma. Bueno para rematar, revisar y cazar erratas.", "Hari saat paruh Ayam (酉) berputar — ketelitian adalah senjatamu. Bagus untuk menyelesaikan, memeriksa, menangkap salah ketik.", "酉のくちばしが巡る日 — 几帳面さが武器だ。仕上げと点検、誤字取りに良い。", "วันที่จะงอยระกา (酉) หมุนเวียน — ความละเอียดคืออาวุธ เหมาะเก็บงาน ตรวจทาน จับคำผิด", "酉鸡喙尖流转之日——细致是武器。收尾、检查、捉错字皆宜。", "酉雞喙尖流轉之日——細緻是武器。收尾、檢查、捉錯字皆宜。"],
    "개(戌)의 의리가 도는 날 — 사람에게 들인 공이 돌아온다. 신세 진 이에게 안부를 넣어라.": ["A day the Dog's (戌) loyalty turns — effort invested in people returns. Send word to those you owe.", "Día de la lealtad del Perro (戌): vuelve lo invertido en la gente. Saluda a quienes les debes.", "Hari saat kesetiaan Anjing (戌) berputar — jerih payah pada orang kembali. Kirimkan salam pada yang pernah membantumu.", "戌の義理が巡る日 — 人に注いだ功が戻る。世話になった者に安否を入れよ。", "วันที่น้ำใจจอ (戌) หมุนเวียน — แรงที่ลงกับผู้คนย้อนกลับมา จงส่งข่าวถึงคนที่เคยมีบุญคุณ", "戌狗义气流转之日——花在人身上的功夫有回报。给欠过人情的人捎个问候。", "戌狗義氣流轉之日——花在人身上的功夫有回報。給欠過人情的人捎個問候。"],
    "돼지(亥)의 너그러움이 도는 날 — 베푼 만큼 돌아온다. 작게 양보하고 크게 얻어라.": ["A day the Pig's (亥) generosity turns — what you give comes back. Yield small, gain big.", "Día de la bondad del Cerdo (亥): lo dado vuelve. Cede en lo pequeño y gana en lo grande.", "Hari saat kemurahan Babi (亥) berputar — yang diberi akan kembali. Mengalah kecil, dapat besar.", "亥の寛大さが巡る日 — 施した分だけ戻る。小さく譲って大きく得よ。", "วันที่ความใจกว้างกุน (亥) หมุนเวียน — ให้ไปเท่าไรได้คืนเท่านั้น ยอมเรื่องเล็กแล้วได้เรื่องใหญ่", "亥猪宽厚流转之日——施多少回多少。小处让，大处得。", "亥豬寬厚流轉之日——施多少回多少。小處讓，大處得。"],
    "일진 천간은 네 비견(比肩) — 나와 어깨를 나란히 하는 기운이다. 혼자 끌던 일을 이 날 밀면 두 배로 나간다. 다만 고집도 두 배니, 맞는 말도 한 박자 늦게 해라.": ["The day's stem is your Bigyeon (比肩) — an energy standing shoulder to shoulder with you. Push a solo project this day and it advances double. But stubbornness doubles too — even right words, say one beat late.", "El tronco del día es tu Bigyeon (比肩): energía hombro con hombro contigo. Empuja hoy lo que llevabas solo y avanza el doble. Pero la terquedad también se duplica: hasta lo correcto, dilo un compás tarde.", "Batang hari ini adalah Bigyeon-mu (比肩) — energi yang berdiri sebahu denganmu. Dorong proyek yang kautarik sendirian hari ini dan majunya dua kali lipat. Tapi keras kepala pun dobel — kata yang benar sekalipun ucapkan satu ketukan lebih lambat.", "日辰の天干はお前の比肩 — 我と肩を並べる気だ。ひとりで引いてきた事をこの日押せば二倍に進む。ただし意地も二倍ゆえ、正しい言葉も一拍遅く言え。", "ลำต้นวันนี้คือพีร์ (比肩) ของเจ้า — พลังที่ยืนเคียงบ่า งานที่ลากคนเดียวถ้าดันวันนี้จะเดินหน้าสองเท่า แต่ความดื้อก็สองเท่า แม้คำที่ถูกก็จงพูดช้าหนึ่งจังหวะ", "日辰天干为你之比肩——与你并肩之气。独自拉扯的事今日一推，进两倍。但固执也翻倍，就算说得对，也慢半拍再说。", "日辰天干為你之比肩——與你並肩之氣。獨自拉扯的事今日一推，進兩倍。但固執也翻倍，就算說得對，也慢半拍再說。"],
    "비견의 날 — 동지가 붙는다. 협업·모임·같이 하는 운동에 좋고, 더치페이 셈만 분명히 하면 탈이 없다.": ["A Bigyeon day — comrades attach. Good for collaboration, gatherings, exercising together; just keep the split-bill math clear and no harm comes.", "Día de Bigyeon: se suman camaradas. Bueno para colaborar, reunirse, entrenar juntos; con las cuentas claras del pago dividido, sin problemas.", "Hari Bigyeon — kawan seperjuangan menempel. Bagus untuk kolaborasi, kumpul, olahraga bareng; asal hitungan patungan jelas, aman.", "比肩の日 — 同志が付く。協業・集まり・共にする運動に良く、割り勘の勘定さえ明確なら障りはない。", "วันพีร์ — สหายเข้ามาเกาะ เหมาะกับงานร่วม การรวมตัว ออกกำลังด้วยกัน แค่หารเท่าให้ชัดก็ไร้ปัญหา", "比肩之日——同道来附。宜协作·聚会·同练，AA的账算清便无碍。", "比肩之日——同道來附。宜協作·聚會·同練，AA的賬算清便無礙。"],
    "일진 천간은 네 겁재(劫財) — 내 몫을 나누자는 기운이다. 이 날의 동업 제안·돈 빌려달란 말은 웃으며 미뤄라.": ["The day's stem is your Geopjae (劫財) — an energy that asks to share your portion. Partnership offers and loan requests today: smile, and postpone them.", "El tronco del día es tu Geopjae (劫財): energía que pide repartir tu parte. Propuestas de sociedad y préstamos hoy: sonríe y posponlos.", "Batang hari ini adalah Geopjae-mu (劫財) — energi yang minta berbagi jatahmu. Tawaran kongsi dan pinjam uang hari ini: tersenyumlah dan tunda.", "日辰の天干はお前の劫財 — 我の取り分を分けようという気だ。この日の共同事業の提案・金を貸せという話は笑って先送りせよ。", "ลำต้นวันนี้คือคู่แข่ง (劫財) — พลังที่ขอแบ่งส่วนของเจ้า ข้อเสนอหุ้นส่วนและคำขอยืมเงินวันนี้ จงยิ้มแล้วเลื่อนไว้ก่อน", "日辰天干为你之劫财——欲分你那份之气。这天的合伙提议·借钱之言，笑着往后推。", "日辰天干為你之劫財——欲分你那份之氣。這天的合夥提議·借錢之言，笑著往後推。"],
    "겁재의 날 — 경쟁자가 힘을 얻는다. 승부는 피하지 말되, 판돈은 작게 걸어라.": ["A Geopjae day — rivals gain strength. Don't dodge the contest, but keep the stakes small.", "Día de Geopjae: los rivales cobran fuerza. No evites el duelo, pero apuesta poco.", "Hari Geopjae — pesaing mendapat tenaga. Jangan hindari pertandingannya, tapi pasang taruhan kecil saja.", "劫財の日 — 競争者が力を得る。勝負は避けるな、だが賭け金は小さく張れ。", "วันคู่แข่ง — คู่แข่งได้พลัง อย่าหนีการประลอง แต่เดิมพันให้น้อย", "劫财之日——对手得势。较量不必躲，赌注要下小。", "劫財之日——對手得勢。較量不必躲，賭注要下小。"],
    "일진 천간은 네 식신(食神) — 먹고 만들고 즐기는 기운이다. 요리·창작·취미에 손맛이 붙고, 몸 컨디션도 순하다.": ["The day's stem is your Siksin (食神) — the energy of eating, making, enjoying. A deft touch comes to cooking, creating, hobbies; the body runs gentle too.", "El tronco del día es tu Siksin (食神): energía de comer, crear y gozar. La sazón llega a cocina, creación y hobbies; el cuerpo también anda manso.", "Batang hari ini adalah Siksin-mu (食神) — energi makan, membuat, menikmati. Sentuhan lihai datang pada masakan, karya, hobi; kondisi badan pun jinak.", "日辰の天干はお前の食神 — 食べて作って楽しむ気だ。料理・創作・趣味に手の味が付き、体の調子も素直だ。", "ลำต้นวันนี้คือพรสวรรค์ (食神) — พลังแห่งการกิน สร้าง และสุขสำราญ ฝีมือจับต้องได้ในการครัว งานสร้างสรรค์ งานอดิเรก สภาพร่างกายก็ราบรื่น", "日辰天干为你之食神——吃、做、乐之气。烹饪·创作·爱好添手感，身体状态也顺。", "日辰天干為你之食神——吃、做、樂之氣。烹飪·創作·愛好添手感，身體狀態也順。"],
    "식신의 날 — 결과물이 남는 일을 해라. 이 날 만든 것은 오래 간다. 맛있는 것을 먹는 것도 운을 먹는 일이다.": ["A Siksin day — do work that leaves something behind. What's made this day lasts long. Eating something delicious is eating luck itself.", "Día de Siksin: haz lo que deje resultado. Lo creado hoy dura mucho. Comer rico también es comer suerte.", "Hari Siksin — kerjakan yang meninggalkan hasil. Yang dibuat hari ini awet lama. Makan enak pun berarti memakan keberuntungan.", "食神の日 — 成果物の残る事をせよ。この日作った物は長く持つ。うまい物を食べるのも運を食べる事だ。", "วันพรสวรรค์ — จงทำงานที่ทิ้งผลงานไว้ ของที่สร้างวันนี้อยู่ทน กินของอร่อยก็คือการกินโชค", "食神之日——做留得下成果的事。这天做的东西经久。吃美味也是在吃运气。", "食神之日——做留得下成果的事。這天做的東西經久。吃美味也是在吃運氣。"],
    "일진 천간은 네 상관(傷官) — 재주가 번뜩이되 입이 앞서는 기운이다. 아이디어는 쏟아내되, 윗사람 앞에선 세 마디 중 한 마디만 해라.": ["The day's stem is your Sanggwan (傷官) — flashing talent with a tongue that runs ahead. Pour out the ideas, but before superiors, speak one word in three.", "El tronco del día es tu Sanggwan (傷官): talento chispeante y lengua adelantada. Derrama ideas, pero ante superiores di una de cada tres palabras.", "Batang hari ini adalah Sanggwan-mu (傷官) — bakat berkilat tapi mulut mendahului. Curahkan ide, tapi di depan atasan ucapkan satu dari tiga kata.", "日辰の天干はお前の傷官 — 才が閃くが口が先走る気だ。アイデアは注ぎ出せ、だが目上の前では三言のうち一言だけ言え。", "ลำต้นวันนี้คือการแสดงออก (傷官) — พรสวรรค์แวบวับแต่ปากไวเกิน เทไอเดียออกมาเถิด แต่ต่อหน้าผู้ใหญ่พูดหนึ่งในสามคำพอ", "日辰天干为你之伤官——才华闪耀而嘴快之气。点子尽管倾泻，但在上位者面前，三句只说一句。", "日辰天干為你之傷官——才華閃耀而嘴快之氣。點子儘管傾瀉，但在上位者面前，三句只說一句。"],
    "상관의 날 — 표현이 빛난다. 글·발표·기획에 쓰면 약이 되고, 뒷말에 쓰면 독이 된다.": ["A Sanggwan day — expression shines. Spent on writing, presenting, planning, it's medicine; spent on gossip, it's poison.", "Día de Sanggwan: brilla la expresión. Usada en escribir, presentar, planear es medicina; en chismes, veneno.", "Hari Sanggwan — ekspresi bersinar. Dipakai untuk menulis, presentasi, merancang jadi obat; dipakai bergunjing jadi racun.", "傷官の日 — 表現が輝く。文・発表・企画に使えば薬になり、陰口に使えば毒になる。", "วันการแสดงออก — การสื่อสารเปล่งประกาย ใช้กับงานเขียน พรีเซนต์ วางแผนคือยา ใช้นินทาลับหลังคือพิษ", "伤官之日——表达生辉。用于文章·发表·企划是药，用于背后闲话是毒。", "傷官之日——表達生輝。用於文章·發表·企劃是藥，用於背後閒話是毒。"],
    "일진 천간은 네 편재(偏財) — 굴러다니는 기회의 돈 기운이다. 눈은 크게 뜨되 전 재산을 싣지는 마라. 소액이면 약, 큰돈이면 독이다.": ["The day's stem is your Pyeonjae (偏財) — the energy of opportunity money rolling around. Open your eyes wide, but don't load your whole fortune. Small sums are medicine; big money is poison.", "El tronco del día es tu Pyeonjae (偏財): dinero de oportunidad rodando. Abre bien los ojos, pero no cargues todo tu patrimonio. Poco es medicina; mucho, veneno.", "Batang hari ini adalah Pyeonjae-mu (偏財) — energi uang peluang yang berserakan. Buka mata lebar-lebar, tapi jangan muat seluruh hartamu. Nominal kecil itu obat; uang besar itu racun.", "日辰の天干はお前の偏財 — 転がるチャンスの金の気だ。目は大きく開け、だが全財産は積むな。少額なら薬、大金なら毒だ。", "ลำต้นวันนี้คือทรัพย์ลาภ (偏財) — พลังเงินแห่งโอกาสที่กลิ้งไปมา เปิดตาให้กว้าง แต่อย่าขนทรัพย์ทั้งหมดขึ้นไป จำนวนน้อยคือยา เงินก้อนใหญ่คือพิษ", "日辰天干为你之偏财——满地滚的机会财之气。眼要睁大，但莫押上全部家当。小额是药，大钱是毒。", "日辰天干為你之偏財——滿地滾的機會財之氣。眼要睜大，但莫押上全部家當。小額是藥，大錢是毒。"],
    "편재의 날 — 뜻밖의 정보·세일·기회가 스친다. 잡되, 오늘 번 것을 오늘 쓰지는 마라.": ["A Pyeonjae day — unexpected tips, sales, chances brush past. Catch them, but don't spend today's earnings today.", "Día de Pyeonjae: rozan datos, ofertas y chances inesperados. Atrápalos, pero no gastes hoy lo ganado hoy.", "Hari Pyeonjae — info tak terduga, diskon, peluang melintas. Tangkaplah, tapi jangan belanjakan hari ini juga hasil hari ini.", "偏財の日 — 思わぬ情報・セール・機会がかすめる。掴め、だが今日稼いだ物を今日使うな。", "วันทรัพย์ลาภ — ข้อมูล เซล โอกาสไม่คาดฝันเฉียดผ่าน จงคว้าไว้ แต่เงินที่ได้วันนี้อย่าใช้วันนี้", "偏财之日——意外的情报·特卖·机会擦身。抓住，但今日所赚莫今日花。", "偏財之日——意外的情報·特賣·機會擦身。抓住，但今日所賺莫今日花。"],
    "일진 천간은 네 정재(正財) — 성실하게 쌓는 돈의 기운이다. 가계부·적금·정산, 차곡차곡 하는 일에 복이 붙는다.": ["The day's stem is your Jeongjae (正財) — the energy of money built diligently. Fortune clings to steady work: bookkeeping, savings, settlements.", "El tronco del día es tu Jeongjae (正財): dinero acumulado con constancia. La fortuna se pega a lo metódico: cuentas, ahorros, saldos.", "Batang hari ini adalah Jeongjae-mu (正財) — energi uang yang ditumpuk dengan tekun. Berkah menempel pada kerja rapi: pembukuan, tabungan, pelunasan.", "日辰の天干はお前の正財 — 誠実に積む金の気だ。家計簿・積立・精算、こつこつやる事に福が付く。", "ลำต้นวันนี้คือทรัพย์มั่นคง (正財) — พลังเงินที่สั่งสมด้วยความขยัน บุญเกาะงานที่ทำทีละนิด บัญชี เงินออม การเคลียร์ยอด", "日辰天干为你之正财——踏实积攒之财气。记账·定存·结算，凡按部就班之事皆有福。", "日辰天干為你之正財——踏實積攢之財氣。記賬·定存·結算，凡按部就班之事皆有福。"],
    "정재의 날 — 꾸준함이 보상받는다. 미뤄둔 돈 정리를 이 날 해라, 새는 구멍이 눈에 보인다.": ["A Jeongjae day — consistency gets rewarded. Sort the postponed finances today; the leaking holes become visible.", "Día de Jeongjae: la constancia se premia. Ordena hoy las finanzas aplazadas; los agujeros que gotean se ven.", "Hari Jeongjae — ketekunan diganjar. Bereskan urusan uang yang tertunda hari ini; lubang bocornya jadi kelihatan.", "正財の日 — 地道さが報われる。先延ばしの金の整理をこの日せよ、漏れる穴が目に見える。", "วันทรัพย์มั่นคง — ความสม่ำเสมอได้รางวัล จัดการเรื่องเงินที่ค้างวันนี้ รูรั่วจะมองเห็นชัด", "正财之日——坚持有报。搁置的钱务今日理，漏财的洞看得见。", "正財之日——堅持有報。擱置的錢務今日理，漏財的洞看得見。"],
    "일진 천간은 네 편관(偏官) — 나를 시험하는 압박의 기운이다. 버겁게 느껴져도 이 날 버틴 것은 근육이 된다. 무리한 일정 하나만 빼라.": ["The day's stem is your Pyeongwan (偏官) — pressure that tests you. It may feel heavy, but what you endure this day becomes muscle. Just drop one overloaded item from the schedule.", "El tronco del día es tu Pyeongwan (偏官): presión que te prueba. Pesa, pero lo resistido hoy se vuelve músculo. Quita solo un exceso de la agenda.", "Batang hari ini adalah Pyeongwan-mu (偏官) — tekanan yang mengujimu. Terasa berat, tapi yang kautahan hari ini jadi otot. Cukup buang satu jadwal yang berlebihan.", "日辰の天干はお前の偏官 — 我を試す圧の気だ。重く感じてもこの日耐えた物は筋肉になる。無理な日程を一つだけ抜け。", "ลำต้นวันนี้คือความท้าทาย (偏官) — แรงกดที่ทดสอบเจ้า หนักหน่อยแต่สิ่งที่ทนได้วันนี้จะกลายเป็นกล้ามเนื้อ แค่ตัดตารางที่หักโหมออกหนึ่งอย่าง", "日辰天干为你之偏官——考验你的压力之气。纵觉吃力，今日扛住的都成肌肉。只需抽掉一项过满的日程。", "日辰天干為你之偏官——考驗你的壓力之氣。縱覺吃力，今日扛住的都成肌肉。只需抽掉一項過滿的日程。"],
    "편관의 날 — 압박이 세다. 정면돌파보다 절차와 원칙 뒤에 서라, 그게 제일 단단한 방패다.": ["A Pyeongwan day — pressure runs strong. Rather than charging head-on, stand behind procedure and principle; that is the sturdiest shield.", "Día de Pyeongwan: presión fuerte. Antes que embestir, ponte tras el procedimiento y el principio: es el escudo más firme.", "Hari Pyeongwan — tekanannya kuat. Alih-alih menerobos frontal, berdirilah di belakang prosedur dan prinsip; itulah perisai terkokoh.", "偏官の日 — 圧が強い。正面突破より手順と原則の後ろに立て、それが一番堅い盾だ。", "วันความท้าทาย — แรงกดหนัก แทนที่จะบุกซึ่งหน้า จงยืนหลังขั้นตอนและหลักการ นั่นคือโล่ที่แข็งแกร่งที่สุด", "偏官之日——压力甚强。与其正面硬闯，不如站在程序与原则之后，那是最硬的盾。", "偏官之日——壓力甚強。與其正面硬闖，不如站在程序與原則之後，那是最硬的盾。"],
    "일진 천간은 네 정관(正官) — 격을 세워 주는 기운이다. 면접·발표·공식 자리에 이 날을 써라, 반듯한 모습이 그대로 점수가 된다.": ["The day's stem is your Jeonggwan (正官) — energy that raises your standing. Use this day for interviews, presentations, official occasions; a proper bearing scores as is.", "El tronco del día es tu Jeonggwan (正官): energía que alza tu categoría. Usa el día para entrevistas, presentaciones y actos oficiales; la compostura puntúa sola.", "Batang hari ini adalah Jeonggwan-mu (正官) — energi yang menegakkan martabatmu. Pakai hari ini untuk wawancara, presentasi, acara resmi; sikap rapi langsung jadi nilai.", "日辰の天干はお前の正官 — 格を立ててくれる気だ。面接・発表・公式の席にこの日を使え、折り目正しい姿がそのまま点数になる。", "ลำต้นวันนี้คือเกียรติยศ (正官) — พลังที่ยกศักดิ์ศรีเจ้า ใช้วันนี้กับสัมภาษณ์ พรีเซนต์ งานทางการ ความเรียบร้อยกลายเป็นคะแนนทันที", "日辰天干为你之正官——立格之气。面试·发表·正式场合用这天，端正模样直接得分。", "日辰天干為你之正官——立格之氣。面試·發表·正式場合用這天，端正模樣直接得分。"],
    "정관의 날 — 규칙이 편이 되어 준다. 서류·신고·허가, 관(官)이 붙는 일은 이 날 순하게 풀린다.": ["A Jeonggwan day — the rules take your side. Documents, filings, permits — anything with 'official' attached unravels gently this day.", "Día de Jeonggwan: las reglas se ponen de tu lado. Papeles, trámites, permisos: lo 'oficial' se resuelve manso hoy.", "Hari Jeonggwan — aturan berpihak padamu. Dokumen, lapor, izin — semua yang berbau 'resmi' terurai jinak hari ini.", "正官の日 — 規則が味方になってくれる。書類・届け出・許可、官の付く事はこの日、素直に解ける。", "วันเกียรติยศ — กฎเข้าข้างเจ้า เอกสาร ยื่นเรื่อง ใบอนุญาต — งานที่มีคำว่า 'ราชการ' คลี่คลายราบรื่นวันนี้", "正官之日——规则站在你这边。文书·申报·许可，凡带'官'之事这天顺解。", "正官之日——規則站在你這邊。文書·申報·許可，凡帶『官』之事這天順解。"],
    "일진 천간은 네 편인(偏印) — 생각이 깊어지는 기운이다. 직감이 예리하니 연구·기획에 좋고, 다만 걱정도 늘어나니 밤샘은 마라.": ["The day's stem is your Pyeonin (偏印) — energy that deepens thought. Intuition sharpens — good for research and planning; but worries multiply too, so no all-nighters.", "El tronco del día es tu Pyeonin (偏印): energía que ahonda el pensamiento. La intuición se afila: bueno para investigar y planear; pero las preocupaciones crecen, así que no trasnoches.", "Batang hari ini adalah Pyeonin-mu (偏印) — energi yang memperdalam pikiran. Intuisi menajam — bagus untuk riset dan perancangan; tapi kekhawatiran ikut bertambah, jadi jangan begadang.", "日辰の天干はお前の偏印 — 考えが深まる気だ。直感が鋭いゆえ研究・企画に良い、ただ心配も増えるゆえ徹夜はするな。", "ลำต้นวันนี้คือญาณทัศน์ (偏印) — พลังที่ทำให้คิดลึก ญาณแหลมคม เหมาะกับวิจัยและวางแผน แต่ความกังวลก็เพิ่ม อย่าโต้รุ่ง", "日辰天干为你之偏印——思虑加深之气。直觉锐利，宜研究·企划；但忧虑也增多，莫熬通宵。", "日辰天干為你之偏印——思慮加深之氣。直覺銳利，宜研究·企劃；但憂慮也增多，莫熬通宵。"],
    "편인의 날 — 혼자만의 시간이 약이 된다. 어려운 공부·까다로운 문제를 이 날 파라, 평소 안 보이던 길이 보인다.": ["A Pyeonin day — time alone becomes medicine. Dig into hard studies and thorny problems today; paths you couldn't see before appear.", "Día de Pyeonin: el tiempo a solas es medicina. Cava hoy en estudios difíciles y problemas espinosos; se ven caminos antes invisibles.", "Hari Pyeonin — waktu sendirian jadi obat. Gali pelajaran sulit dan soal pelik hari ini; jalan yang biasanya tak terlihat akan tampak.", "偏印の日 — ひとりの時間が薬になる。難しい勉強・厄介な問題をこの日掘れ、普段見えぬ道が見える。", "วันญาณทัศน์ — เวลาตามลำพังคือยา ขุดวิชายากและโจทย์หินวันนี้ จะเห็นทางที่ปกติมองไม่เห็น", "偏印之日——独处即良药。难学问·棘手题今日深挖，平日看不见的路会显现。", "偏印之日——獨處即良藥。難學問·棘手題今日深挖，平日看不見的路會顯現。"],
    "일진 천간은 네 정인(正印) — 나를 살찌우는 배움과 귀인의 기운이다. 어른의 조언, 오는 연락을 미루지 마라.": ["The day's stem is your Jeongin (正印) — the energy of learning and benefactors that nourish you. Elders' advice, incoming contact — don't put them off.", "El tronco del día es tu Jeongin (正印): energía de aprendizaje y benefactores que te nutren. Consejos de mayores, contactos entrantes: no los aplaces.", "Batang hari ini adalah Jeongin-mu (正印) — energi ilmu dan penolong yang menggemukkanmu. Nasihat orang tua, kontak yang masuk — jangan ditunda.", "日辰の天干はお前の正印 — 我を肥やす学びと貴人の気だ。目上の助言、来る連絡を先送りするな。", "ลำต้นวันนี้คือการเรียนรู้ (正印) — พลังแห่งวิชาและผู้มีพระคุณที่หล่อเลี้ยงเจ้า คำแนะนำผู้ใหญ่ การติดต่อที่เข้ามา อย่าผัดผ่อน", "日辰天干为你之正印——滋养你的学问与贵人之气。长辈忠告、来的联络，莫要拖延。", "日辰天干為你之正印——滋養你的學問與貴人之氣。長輩忠告、來的聯絡，莫要拖延。"],
    "정인의 날 — 문서와 도장에 운이 붙는다. 계약서 검토·신청·등록은 이 날 해라. 이 날 배운 것은 오래 남는다.": ["A Jeongin day — luck clings to documents and seals. Review contracts, apply, register today. What's learned this day remains long.", "Día de Jeongin: la suerte se pega a documentos y sellos. Revisa contratos, solicita, regístrate hoy. Lo aprendido hoy perdura.", "Hari Jeongin — keberuntungan menempel pada dokumen dan stempel. Tinjau kontrak, ajukan, daftarkan hari ini. Yang dipelajari hari ini bertahan lama.", "正印の日 — 書類と印鑑に運が付く。契約書の検討・申請・登録はこの日せよ。この日学んだ事は長く残る。", "วันการเรียนรู้ — โชคเกาะเอกสารและตราประทับ ตรวจสัญญา ยื่นเรื่อง ลงทะเบียนวันนี้ สิ่งที่เรียนวันนี้อยู่ยาว", "正印之日——文书与印章沾运。审合同·申请·注册今日办。今日所学留得久。", "正印之日——文書與印章沾運。審合同·申請·註冊今日辦。今日所學留得久。"]
  });
})();
